-- OPTIONAL: original APEX demo content, NOT ICFES. Local/test projects only.
BEGIN;
SET LOCAL search_path TO apex_private, pg_catalog;
DO $$ BEGIN IF EXISTS(SELECT 1 FROM evaluacion WHERE id='diagnostico-v1') THEN RAISE EXCEPTION 'Demo already present: do not reapply'; END IF; END $$;
UPDATE pregunta SET procedencia='propia_demo',estado_revision='revisada' WHERE id_fuente='propia-v1';
UPDATE material_estudio SET publicado=true WHERE id_fuente='propia-v1';
UPDATE evaluacion SET publicada=true WHERE id='diagnostico-v1';
COMMIT;
