INSERT INTO fuente(id,titulo,organismo,referencia_edicion) VALUES('propia-v1','Contenido propio de demostración APEX','APEX','v1 · No es material oficial ICFES');
INSERT INTO material_estudio(id,id_fuente,titulo,contenido,version) VALUES('porcentajes','propia-v1','Porcentajes, paso a paso','Un porcentaje expresa una parte de cada cien. Para calcular un descuento, multiplica el precio por el porcentaje dividido entre 100 y resta ese valor. Ejemplo distinto al diagnóstico: 10 % de $50.000 son $5.000; el precio final es $45.000. Practica: calcula el 20 % de 80.',1);
INSERT INTO material_estudio(id,id_fuente,titulo,contenido,version) VALUES('promedios','propia-v1','Lee los datos con calma','El promedio es la suma de los valores dividida entre su cantidad. Para 4, 6 y 8: (4 + 6 + 8) / 3 = 6. Antes de operar, identifica la unidad y lo que pide la pregunta. En una probabilidad simple, divide los casos favorables entre los casos posibles igualmente probables.',1);
INSERT INTO material_estudio(id,id_fuente,titulo,contenido,version) VALUES('areas','propia-v1','Distingue área y perímetro','El área de un rectángulo es base por altura; su unidad es cuadrada. El perímetro suma todos sus lados. Para un rectángulo de 3 m por 2 m: área = 6 m² y perímetro = 10 m. Dibuja la figura y escribe las unidades antes de calcular.',1);
