INSERT INTO pregunta(id,id_fuente,id_nucleo,id_competencia,enunciado,version) VALUES('q1','propia-v1','numeros','resolver','Una libreta cuesta $20.000 y tiene un descuento del 15 %. ¿Cuánto pagas?',1);
INSERT INTO pregunta(id,id_fuente,id_nucleo,id_competencia,enunciado,version) VALUES('q2','propia-v1','numeros','resolver','Una receta para 4 personas usa 300 g de arroz. ¿Cuánto se necesita para 6 personas?',1);
INSERT INTO pregunta(id,id_fuente,id_nucleo,id_competencia,enunciado,version) VALUES('q3','propia-v1','datos','interpretar','Las notas son 2, 3, 3 y 4. ¿Cuál es su promedio?',1);
INSERT INTO pregunta(id,id_fuente,id_nucleo,id_competencia,enunciado,version) VALUES('q4','propia-v1','datos','resolver','En una bolsa hay 3 fichas azules y 2 verdes. ¿Cuál es la probabilidad de sacar una verde?',1);
INSERT INTO pregunta(id,id_fuente,id_nucleo,id_competencia,enunciado,version) VALUES('q5','propia-v1','geometria','resolver','Un rectángulo mide 8 m de largo y 5 m de ancho. ¿Cuál es su área?',1);
INSERT INTO pregunta(id,id_fuente,id_nucleo,id_competencia,enunciado,version) VALUES('q6','propia-v1','datos','interpretar','Una biblioteca prestó 12 libros el lunes y 18 el martes. ¿Cuántos prestó en total?',1);
INSERT INTO pregunta(id,id_fuente,id_nucleo,id_competencia,enunciado,version) VALUES('q7','propia-v1','numeros','resolver','Si 3x + 6 = 21, ¿cuál es el valor de x?',1);
